-- Raw canvas submission counts for schema >= 37, release channel, 2026-02-01 to 2026-03-27
-- Compares actual n_raw against expected (TARGET=50 / full-analysis count)
-- One row per canvas type + hash prefix

WITH base AS (

  SELECT 'canvas01'    AS canvas, SUBSTR(metrics.string.characteristics_canvasdata1,          1,13) AS prefix, COUNTIF(metrics.text2.characteristics_canvasdata1_raw          IS NOT NULL) AS n_raw, COUNT(*) AS n FROM `mozdata.firefox_desktop.user_characteristics` WHERE metrics.string.characteristics_canvasdata1           IS NOT NULL AND metrics.string.characteristics_canvasdata1           != '' AND metrics.quantity.characteristics_submission_schema >= 37 AND metrics.string.characteristics_channel = 'release' AND DATE(submission_timestamp) >= '2026-02-01' AND DATE(submission_timestamp) < '2026-03-27' GROUP BY prefix UNION ALL
  SELECT 'canvas02'    AS canvas, SUBSTR(metrics.string.characteristics_canvasdata2,          1,13) AS prefix, COUNTIF(metrics.text2.characteristics_canvasdata2_raw          IS NOT NULL) AS n_raw, COUNT(*) AS n FROM `mozdata.firefox_desktop.user_characteristics` WHERE metrics.string.characteristics_canvasdata2           IS NOT NULL AND metrics.string.characteristics_canvasdata2           != '' AND metrics.quantity.characteristics_submission_schema >= 37 AND metrics.string.characteristics_channel = 'release' AND DATE(submission_timestamp) >= '2026-02-01' AND DATE(submission_timestamp) < '2026-03-27' GROUP BY prefix UNION ALL
