  SELECT 'canvas05'    AS canvas, SUBSTR(metrics.string.characteristics_canvasdata5,          1,13) AS prefix, COUNTIF(metrics.text2.characteristics_canvasdata5_raw          IS NOT NULL) AS n_raw, COUNT(*) AS n FROM `mozdata.firefox_desktop.user_characteristics` WHERE metrics.string.characteristics_canvasdata5           IS NOT NULL AND metrics.string.characteristics_canvasdata5           != '' AND metrics.quantity.characteristics_submission_schema >= 37 AND metrics.string.characteristics_channel = 'release' AND DATE(submission_timestamp) >= '2026-02-01' AND DATE(submission_timestamp) < '2026-03-27' GROUP BY prefix UNION ALL
