  SELECT 'canvas11'    AS canvas, SUBSTR(metrics.string.characteristics_canvasdata11_webgl,   1,13) AS prefix, COUNTIF(metrics.text2.characteristics_canvasdata11_webgl_raw   IS NOT NULL) AS n_raw, COUNT(*) AS n FROM `mozdata.firefox_desktop.user_characteristics` WHERE metrics.string.characteristics_canvasdata11_webgl    IS NOT NULL AND metrics.string.characteristics_canvasdata11_webgl    != '' AND metrics.quantity.characteristics_submission_schema >= 37 AND metrics.string.characteristics_channel = 'release' AND DATE(submission_timestamp) >= '2026-02-01' AND DATE(submission_timestamp) < '2026-03-27' GROUP BY prefix UNION ALL
  SELECT 'canvas12'    AS canvas, SUBSTR(metrics.string.characteristics_canvasdata12_fingerprintjs1, 1,13) AS prefix, COUNTIF(metrics.text2.characteristics_canvasdata12_fingerprintjs1_raw IS NOT NULL) AS n_raw, COUNT(*) AS n FROM `mozdata.firefox_desktop.user_characteristics` WHERE metrics.string.characteristics_canvasdata12_fingerprintjs1  IS NOT NULL AND metrics.string.characteristics_canvasdata12_fingerprintjs1  != '' AND metrics.quantity.characteristics_submission_schema >= 37 AND metrics.string.characteristics_channel = 'release' AND DATE(submission_timestamp) >= '2026-02-01' AND DATE(submission_timestamp) < '2026-03-27' GROUP BY prefix UNION ALL
  SELECT 'canvas13'    AS canvas, SUBSTR(metrics.string.characteristics_canvasdata13_fingerprintjs2, 1,13) AS prefix, COUNTIF(metrics.text2.characteristics_canvasdata13_fingerprintjs2_raw IS NOT NULL) AS n_raw, COUNT(*) AS n FROM `mozdata.firefox_desktop.user_characteristics` WHERE metrics.string.characteristics_canvasdata13_fingerprintjs2  IS NOT NULL AND metrics.string.characteristics_canvasdata13_fingerprintjs2  != '' AND metrics.quantity.characteristics_submission_schema >= 37 AND metrics.string.characteristics_channel = 'release' AND DATE(submission_timestamp) >= '2026-02-01' AND DATE(submission_timestamp) < '2026-03-27' GROUP BY prefix UNION ALL

  SELECT 'canvas01_sw' AS canvas, SUBSTR(metrics.string.characteristics_canvasdata1_software,  1,13) AS prefix, COUNTIF(metrics.text2.characteristics_canvasdata1_software_raw  IS NOT NULL) AS n_raw, COUNT(*) AS n FROM `mozdata.firefox_desktop.user_characteristics` WHERE metrics.string.characteristics_canvasdata1_software   IS NOT NULL AND metrics.string.characteristics_canvasdata1_software   != '' AND metrics.quantity.characteristics_submission_schema >= 37 AND metrics.string.characteristics_channel = 'release' AND DATE(submission_timestamp) >= '2026-02-01' AND DATE(submission_timestamp) < '2026-03-27' GROUP BY prefix UNION ALL
  SELECT 'canvas02_sw' AS canvas, SUBSTR(metrics.string.characteristics_canvasdata2_software,  1,13) AS prefix, COUNTIF(metrics.text2.characteristics_canvasdata2_software_raw  IS NOT NULL) AS n_raw, COUNT(*) AS n FROM `mozdata.firefox_desktop.user_characteristics` WHERE metrics.string.characteristics_canvasdata2_software   IS NOT NULL AND metrics.string.characteristics_canvasdata2_software   != '' AND metrics.quantity.characteristics_submission_schema >= 37 AND metrics.string.characteristics_channel = 'release' AND DATE(submission_timestamp) >= '2026-02-01' AND DATE(submission_timestamp) < '2026-03-27' GROUP BY prefix UNION ALL
  SELECT 'canvas03_sw' AS canvas, SUBSTR(metrics.string.characteristics_canvasdata3_software,  1,13) AS prefix, COUNTIF(metrics.text2.characteristics_canvasdata3_software_raw  IS NOT NULL) AS n_raw, COUNT(*) AS n FROM `mozdata.firefox_desktop.user_characteristics` WHERE metrics.string.characteristics_canvasdata3_software   IS NOT NULL AND metrics.string.characteristics_canvasdata3_software   != '' AND metrics.quantity.characteristics_submission_schema >= 37 AND metrics.string.characteristics_channel = 'release' AND DATE(submission_timestamp) >= '2026-02-01' AND DATE(submission_timestamp) < '2026-03-27' GROUP BY prefix UNION ALL
  SELECT 'canvas04_sw' AS canvas, SUBSTR(metrics.string.characteristics_canvasdata4_software,  1,13) AS prefix, COUNTIF(metrics.text2.characteristics_canvasdata4_software_raw  IS NOT NULL) AS n_raw, COUNT(*) AS n FROM `mozdata.firefox_desktop.user_characteristics` WHERE metrics.string.characteristics_canvasdata4_software   IS NOT NULL AND metrics.string.characteristics_canvasdata4_software   != '' AND metrics.quantity.characteristics_submission_schema >= 37 AND metrics.string.characteristics_channel = 'release' AND DATE(submission_timestamp) >= '2026-02-01' AND DATE(submission_timestamp) < '2026-03-27' GROUP BY prefix UNION ALL
  SELECT 'canvas05_sw' AS canvas, SUBSTR(metrics.string.characteristics_canvasdata5_software,  1,13) AS prefix, COUNTIF(metrics.text2.characteristics_canvasdata5_software_raw  IS NOT NULL) AS n_raw, COUNT(*) AS n FROM `mozdata.firefox_desktop.user_characteristics` WHERE metrics.string.characteristics_canvasdata5_software   IS NOT NULL AND metrics.string.characteristics_canvasdata5_software   != '' AND metrics.quantity.characteristics_submission_schema >= 37 AND metrics.string.characteristics_channel = 'release' AND DATE(submission_timestamp) >= '2026-02-01' AND DATE(submission_timestamp) < '2026-03-27' GROUP BY prefix UNION ALL
