  SELECT 'canvas09_sw' AS canvas, SUBSTR(metrics.string.characteristics_canvasdata9_software,  1,13) AS prefix, COUNTIF(metrics.text2.characteristics_canvasdata9_software_raw  IS NOT NULL) AS n_raw, COUNT(*) AS n FROM `mozdata.firefox_desktop.user_characteristics` WHERE metrics.string.characteristics_canvasdata9_software   IS NOT NULL AND metrics.string.characteristics_canvasdata9_software   != '' AND metrics.quantity.characteristics_submission_schema >= 37 AND metrics.string.characteristics_channel = 'release' AND DATE(submission_timestamp) >= '2026-02-01' AND DATE(submission_timestamp) < '2026-03-27' GROUP BY prefix UNION ALL
