)

SELECT
  canvas,
  prefix,
  n,
  n_raw,
  ROUND(100.0 * n_raw / n, 4) AS raw_pct,
  ROUND(50.0 / n, 7)          AS expected_prob,
  ROUND(50.0 * n_raw / n / (50.0 / n), 1) AS ratio_vs_target  -- actual_prob / expected_prob
FROM base
ORDER BY canvas, n DESC
